from pathlib import Path
import json,re
ROOT=Path(__file__).resolve().parents[2];base=ROOT/'gauntlet/versions/jace/v0.1-real/deck.dck';original=base.read_text()
packages={
'v0.8-codex-survival':{'purpose':'Preferred first three-card trial: early exile interaction, an answer to lethal attacks and the requested anti-swarm payoff.','swaps':[("White Sun's Twilight",'Massacre Wurm','Twilight needs seven mana to wipe and makes Mites that cannot block; Wurm can shrink opposing small creatures while keeping your tokens and is a Jace hit.'),('Overwrite the Multiverse','Anguished Unmaking','Keep Sunfall as the cheaper exile board wipe; add an instant nonland exile answer for recursive/indestructible threats. Costs 3 life and does not bypass hexproof.'),('Synthetic Destiny','Aetherize','Trade a six-mana delayed transformation spell for a four-mana defensive answer to attacking armies, including unblockable creatures. Cannot undo attack triggers; nontoken creatures can be recast.')], 'caveat':'These are best-fit recommendations to trial, not measured individual upgrades. Losing Synthetic Destiny costs a real protection/polymorph option that Forge underuses. Wurm needs BBB when hard cast and does not sweep already-large tokens.'},
'v0.8-codex-exile':{'purpose':'Isolate two extra instant exile answers against large/recurrent creatures and troublesome nonland engines, keeping owned Despark.','swaps':[('Overwrite the Multiverse','Anguished Unmaking','Instant exile of any targetable nonland permanent; Sunfall retained for a full exile reset.'),('Synthetic Destiny','Reality Shift','Two-mana creature exile without the 4+ mana-value restriction of Despark; opponent manifests a 2/2 that may turn face up.')], 'caveat':'Two fewer mass effects; this may lose ground to wide boards. Exile does not prevent a commander returning to the command zone. Does not answer hexproof. Massacre Wurm is not in the physical baseline; this is an isolated alternate diagnostic, while the preferred survival list adds it.'},
'v0.8-codex-swarms':{'purpose':'Isolate a cheaper full creature reset and a one-sided small-creature payoff against Lathril/Krenko/Chatterfang.','swaps':[("White Sun's Twilight",'Massacre Wurm','Fresh 1/1 and 2/2 armies can die to the entry effect; preserves friendly fodder. Does not handle pumped larger armies by itself.'),('Martial Coup','Wrath of God','Four mana for a full creature wipe instead of requiring X>=5 (seven total mana).')], 'caveat':'Loses two token-making X spells; Wrath kills your own creature board and does not exile or beat indestructible. Sunfall and Overwrite retained. Wurm hard casting raises black requirements.'},
'v0.8-codex-owned-engine':{'purpose':'No-purchase diagnostic: add recurring blocking/fodder capacity and an owned payoff that has visibly prevented a loss.','swaps':[('Synthetic Destiny','Dreadhorde Invasion','Two-mana recurring Army source; one Army grows, with a new Army only after the old one is gone. Costs one life each upkeep.'),('Overwrite the Multiverse','Darksteel Angel','Owned indestructible payoff: verified can’t-lose replacement saved a game at -1 life in C1 pod16-g4.')], 'caveat':'A nine-mana card can clog the hand. Army power grows above the current sim’s power-2 Jace exile limit. Removal of two expensive effects is a real tradeoff; no free card is automatically an upgrade. This alternate diagnostic does not buy/install Massacre Wurm; the preferred survival recommendation still includes Patrick’s requested Wurm.'}
}
live=json.loads((ROOT/'analysis/jace-recommendation/scryfall.json').read_text());assert not live.get('not_found');cards={c['name']:c for c in live['data']}
for v,data in packages.items():
 folder=ROOT/'gauntlet/versions/jace'/v
 if folder.exists():raise RuntimeError('Version already exists: '+v)
 folder.mkdir()
 s=original.replace('Name=jace-v0.1-real','Name=jace-'+v)
 for old,new,why in data['swaps']:
  assert s.count('1 '+old+'\n')==1 and '1 '+new+'\n' not in s
  s=s.replace('1 '+old+'\n','1 '+new+'\n');c=cards[new];assert c['legalities']['commander']=='legal' and not c.get('game_changer') and set(c['color_identity'])<=set('WUBR')
 assert sum(int(l.split(' ',1)[0]) for l in s.splitlines() if l[:1].isdigit())==100
 for name in ['Dreamtide Whale','Triplicate Titan','Loyal Tutor','Despark','Sunfall','Staff of Compleation','Cursed Mirror','Fellwar Stone','Azorius Signet','Talisman of Indulgence','Talisman of Creativity','Rakdos Signet','Izzet Signet']:
  assert '1 '+name+'\n'in s
 (folder/'deck.dck').write_text(s)
 lines=['# '+v,'','Built by Codex 2026-10-29 directly from Patrick’s v0.1-real physical baseline. **Untested.** No existing list, engine or run altered.','',data['purpose'],'','| Out | In | Reason |','|---|---|---|']
 for old,new,why in data['swaps']:lines.append(f'| {old} | {new} | {why} |')
 lines+=['','## Constraints and caveats','',data['caveat'],'','All 39 lands and all baseline mana rocks retained, including Staff of Compleation and Cursed Mirror. Dreamtide Whale, Triplicate Titan, Loyal Tutor and owned Despark retained. No Skrelv’s Hive: its Mites cannot block. Each file contains 100 cards, singleton except basic lands.','', 'New card Forge scripts exist and have no AI:RemoveDeck flag. Reality Shift has a large-creature target preference; Aetherize uses existing SmartAi logic but may be constrained by mana/timing. No new AI flags or logic. Current Scryfall batch confirms all additions are legal in WUBR and not Game Changers.','', '## Hand-off to Claude C6','',f'`node gauntlet/gauntlet.js jace {v} 10 --smart --politics --keeptokens --par=2`','', 'Use the shared process budget; do not run this command until the C6 lane chooses a time. Match the physical baseline’s first ten pods/seeds and frozen engine. A 10-game test checks card use, color problems and gross failure, not close win rates. Run the preferred survival package first, then targeted alternatives as needed. Fix/flag timeout scoring in both comparisons.','', 'Record actual casts/activations, incoming combat and life-loss, resolved -3 counts and fodder availability; do not rank payoffs from cast-only win rates. See ../../../../JACE-RECOMMENDATION.md.']
 (folder/'changes.md').write_text('\n'.join(lines)+'\n')
print('Built',len(packages),'packages directly from v0.1-real; 100 cards each; all lands/rocks retained.')
(ROOT/'analysis/jace-recommendation/packages.json').write_text(json.dumps(packages,indent=2)+'\n')
